/**
 * Where the browser keeps its keys.
 *
 * This is the part of the web client that is genuinely weaker than the phone's,
 * and pretending otherwise would be the dishonest option.
 *
 * On Android the identity is sealed by a hardware-backed key that cannot be
 * exported, so the blob on disk is useless off the device. A browser has no
 * equivalent that a page can reach: IndexedDB is readable by any script running
 * on the origin. So what this file does is:
 *
 *  - encrypt the identity with a non-extractable AES-GCM key generated by
 *    SubtleCrypto, held as a CryptoKey in IndexedDB;
 *  - keep the ciphertext and IV in IndexedDB as well.
 *
 * The non-extractable key cannot be read by JavaScript, so a stolen *copy of the
 * database files* is not enough. It is not protection against script injection
 * on the page while it is open, and it is not protection against someone with
 * the unlocked browser profile. Both of those are stated in the UI rather than
 * quietly assumed away.
 */

const DB_NAME = "veil";
const DB_VERSION = 1;
const STORE = "keys";

interface StoredIdentity {
  iv: Uint8Array;
  ciphertext: Uint8Array;
}

async function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("could not open IndexedDB"));
  });
}

async function get<T>(key: string): Promise<T | undefined> {
  const db = await openDb();
  try {
    return await new Promise<T | undefined>((resolve, reject) => {
      const tx = db.transaction(STORE, "readonly");
      const request = tx.objectStore(STORE).get(key);
      request.onsuccess = () => resolve(request.result as T | undefined);
      request.onerror = () => reject(request.error);
    });
  } finally {
    db.close();
  }
}

async function put(key: string, value: unknown): Promise<void> {
  const db = await openDb();
  try {
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).put(value, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } finally {
    db.close();
  }
}

async function remove(key: string): Promise<void> {
  const db = await openDb();
  try {
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).delete(key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } finally {
    db.close();
  }
}

export class Vault {
  private keyPromise: Promise<CryptoKey> | null = null;

  /** The wrapping key, created on first use and never exportable. */
  private async wrappingKey(): Promise<CryptoKey> {
    if (this.keyPromise) return this.keyPromise;

    this.keyPromise = (async () => {
      const existing = await get<CryptoKey>("wrapping-key");
      if (existing) return existing;

      const key = await crypto.subtle.generateKey(
        { name: "AES-GCM", length: 256 },
        // Non-extractable: JavaScript cannot read the raw bytes, so the key
        // cannot be exfiltrated by a script that only gets its handle.
        false,
        ["encrypt", "decrypt"],
      );
      await put("wrapping-key", key);
      return key;
    })();

    return this.keyPromise;
  }

  private async seal(plaintext: Uint8Array): Promise<StoredIdentity> {
    const key = await this.wrappingKey();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ciphertext = new Uint8Array(
      await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, plaintext),
    );
    return { iv, ciphertext };
  }

  private async unseal(stored: StoredIdentity): Promise<Uint8Array | null> {
    const key = await this.wrappingKey();
    try {
      const plain = await crypto.subtle.decrypt(
        { name: "AES-GCM", iv: stored.iv },
        key,
        stored.ciphertext,
      );
      return new Uint8Array(plain);
    } catch {
      // A different profile, a cleared site, or a key that no longer matches.
      // Report it rather than minting a new identity silently: on this client
      // there is no account recovery either.
      return null;
    }
  }

  // ---- Identity ---------------------------------------------------------

  async hasIdentity(): Promise<boolean> {
    return (await get<StoredIdentity>("identity")) !== undefined;
  }

  async loadIdentity(): Promise<Uint8Array | null> {
    const stored = await get<StoredIdentity>("identity");
    if (!stored) return null;
    return this.unseal(stored);
  }

  async storeIdentity(secrets: Uint8Array): Promise<void> {
    await put("identity", await this.seal(secrets));
  }

  /** True when an identity exists but cannot be decrypted any more. */
  async isIdentityLost(): Promise<boolean> {
    const stored = await get<StoredIdentity>("identity");
    if (!stored) return false;
    return (await this.unseal(stored)) === null;
  }

  async clearIdentity(): Promise<void> {
    await remove("identity");
    await remove("wrapping-key");
  }

  // ---- Protocol state ---------------------------------------------------
  //
  // Prekey state and sessions carry private keys too, so they go through the
  // same seal. The pin registry is public keys only, but keeping it here means
  // one place to reason about.

  async loadPreKeyState(): Promise<Uint8Array | null> {
    const stored = await get<StoredIdentity>("prekeys");
    return stored ? this.unseal(stored) : null;
  }

  async storePreKeyState(blob: Uint8Array): Promise<void> {
    await put("prekeys", await this.seal(blob));
  }

  async loadRegistry(): Promise<Uint8Array | null> {
    const stored = await get<StoredIdentity>("registry");
    return stored ? this.unseal(stored) : null;
  }

  async storeRegistry(blob: Uint8Array): Promise<void> {
    await put("registry", await this.seal(blob));
  }

  async loadSession(peerId: string): Promise<Uint8Array | null> {
    const stored = await get<StoredIdentity>(`session:${peerId}`);
    return stored ? this.unseal(stored) : null;
  }

  async storeSession(peerId: string, blob: Uint8Array): Promise<void> {
    await put(`session:${peerId}`, await this.seal(blob));
  }

  async removeSession(peerId: string): Promise<void> {
    await remove(`session:${peerId}`);
  }

  // ---- Peer index -------------------------------------------------------
  //
  // The registry blob the engine exports is the authority on pins, but it is an
  // opaque byte string: it cannot be enumerated from JavaScript to rebuild a
  // peer list after a reload. This is that list, kept plainly because it is
  // only names — every actual key lives in the sealed blobs above.

  async loadPeerIds(): Promise<string[] | null> {
    return (await get<string[]>("peer-ids")) ?? null;
  }

  async storePeerIds(ids: string[]): Promise<void> {
    await put("peer-ids", ids);
  }

  // ---- Transcript -------------------------------------------------------
  //
  // Message text is the one thing that is *not* sealed: it is written to
  // IndexedDB in the clear, because sealing it with the same non-extractable
  // key would add no real protection against the threat model above (script on
  // the page) and would cost a decrypt on every render. It is stored under a
  // separate key so a future version can seal it without a migration.

  async loadMessages(peerId: string): Promise<StoredMessage[]> {
    return (await get<StoredMessage[]>(`messages:${peerId}`)) ?? [];
  }

  async storeMessages(peerId: string, messages: StoredMessage[]): Promise<void> {
    await put(`messages:${peerId}`, messages);
  }

  // ---- Groups -----------------------------------------------------------
  //
  // Group state carries chain keys: every incoming chain decrypts that sender's
  // messages and the outgoing chain can forge them. It is sealed like ratchet
  // state, for the same reason.

  async loadGroupState(): Promise<Uint8Array | null> {
    const stored = await get<StoredIdentity>("group-state");
    return stored ? this.unseal(stored) : null;
  }

  async storeGroupState(blob: Uint8Array): Promise<void> {
    await put("group-state", await this.seal(blob));
  }

  /** The group ids this client is in, so a reload can enumerate them. */
  async loadGroupIds(): Promise<string[] | null> {
    return (await get<string[]>("group-ids")) ?? null;
  }

  async storeGroupIds(ids: string[]): Promise<void> {
    await put("group-ids", ids);
  }

  // ---- Device identity --------------------------------------------------

  /** This device's hex id, so a reload keeps the same device rather than
   *  minting a second one for the same account. */
  async loadDeviceId(): Promise<string | null> {
    return (await get<string>("device-id")) ?? null;
  }

  async storeDeviceId(id: string): Promise<void> {
    await put("device-id", id);
  }

  async loadGroupMessages(groupId: string): Promise<GroupMessageRecord[]> {
    return (await get<GroupMessageRecord[]>(`group-messages:${groupId}`)) ?? [];
  }

  async storeGroupMessages(groupId: string, messages: GroupMessageRecord[]): Promise<void> {
    await put(`group-messages:${groupId}`, messages);
  }

  async clearAll(): Promise<void> {
    const db = await openDb();
    db.close();
    await new Promise<void>((resolve, reject) => {
      const request = indexedDB.deleteDatabase(DB_NAME);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
      request.onblocked = () => resolve();
    });
  }
}

export interface StoredMessage {
  id: number;
  peerId: string;
  outgoing: boolean;
  text: string;
  timestamp: number;
  state: "queued" | "sent" | "failed";
}

/**
 * One group message, as stored.
 *
 * A separate type from StoredMessage because a group message has no peer: the
 * sender is a member id and the conversation is the group.
 */
export interface GroupMessageRecord {
  groupId: string;
  senderId: string;
  text: string;
  at: number;
}